# [SAME-SCENARIO] stream_completion.py\nimport os\nfrom model_client import get_llm_client\nfrom model_models import PromptRequest\n\ndef stream_completion(prompt: str) -> None:\n    \"\"\"Stream partial output tokens from a hosted LLM.\n    Uses the provider configured in environment variables.\n    \"\"\"\n    client = get_llm_client()\n    request = PromptRequest(\n        messages=[{\"role\": \"user\", \"content\": prompt}],\n        model=\"gpt-4o-mini\",  # Model identifier for the selected provider\n    )\n    # Assuming the client supports an iterable response stream\n    for chunk in client.chat_completions_stream(request):\n        # chunk is expected to have 'content' with partial tokens\n        print(chunk[\"content\"], end=\"\", flush=True)\n